    let mut kind_nameonly: BTreeMap<&'static str, usize> = BTreeMap::new();
    let mut nameonly_recovery_mk: BTreeMap<String, usize> = BTreeMap::new();
    let mut wrapper_peel_clone = 0usize;
    let mut r6_rust = 0usize;
