#!/usr/bin/env python3
"""Refined free_multi fixable estimator with FAITHFUL import->path narrowing.

Matcher tiers (the proposed option-B resolver, mirrored):
  1. absolute dotted module `a.b.c`  -> candidate path endswith `a/b/c.py`
  2. relative module `.x` / `..x`     -> resolve levels-up from caller dir, then path match
  3. bare package `pkg`               -> candidate parent-dir == pkg  (R3 dir_hit)
A free_multi site is FIXABLE iff the caller imports the bare name and the matcher
narrows the cross-file candidate set to exactly 1.
"""
import os, re, sys, collections

root = os.path.expanduser(sys.argv[1])
exts = tuple(sys.argv[2].split(",")) if len(sys.argv) > 2 else (".py",)

DEF = re.compile(r'^(?:async\s+)?def\s+([A-Za-z_]\w*)\s*\(')
CALL = re.compile(r'(?<![.\w])([A-Za-z_]\w*)\s*\(')
FROM_IMP = re.compile(r'^\s*from\s+([.\w]+)\s+import\s+(.+)$')
KW = set('if for while return and or not in is print len range str int list dict set '
         'tuple isinstance super type open with yield assert raise lambda else elif '
         'def class try except finally import from as None True False'.split())

files = []
for dp, dn, fn in os.walk(root):
    if any(s in dp for s in ('/.git', '/node_modules', '/target')):
        continue
    for f in fn:
        if f.endswith(exts):
            files.append(os.path.join(dp, f))

free_defs = collections.defaultdict(set)
per_file_free = collections.defaultdict(set)
per_file_imports = {}
raw = {}
for path in files:
    try:
        txt = open(path, encoding="utf-8", errors="replace").read()
    except Exception:
        continue
    raw[path] = txt
    imps = {}
    for line in txt.splitlines():
        m = DEF.match(line)
        if m and not line[:1].isspace():
            free_defs[m.group(1)].add(path); per_file_free[path].add(m.group(1))
        fm = FROM_IMP.match(line)
        if fm:
            mod = fm.group(1)
            for piece in fm.group(2).split(','):
                piece = piece.strip().strip('()')
                if not piece or piece == '*':
                    continue
                name = piece.split(' as ')[-1].strip()
                if re.fullmatch(r'[A-Za-z_]\w*', name):
                    imps[name] = mod
