    """Return subset of cands consistent with `module` imported at `caller`."""
    if module.startswith('.'):                      # relative
        lvl = len(module) - len(module.lstrip('.'))
        tail = module[lvl:].replace('.', '/')       # remainder after dots
        base = os.path.dirname(norm(caller))
        for _ in range(lvl - 1):
            base = os.path.dirname(base)
        target = (base + '/' + tail).strip('/') if tail else base
        return [c for c in cands if norm(c) == target or os.path.dirname(norm(c)) == target]
    parts = module.split('.')
    suffix = '/'.join(parts)
    hit = [c for c in cands if norm(c) == suffix]            # tier 1: file path match
    if hit:
        return hit
    return [c for c in cands if os.path.basename(os.path.dirname(norm(c))) == parts[-1]]  # tier 3 dir

fm_sites = fm_edges = fixable_1 = external = ambiguous = narrow_multi = 0
fanout_fixable = []
for path in files:
    txt = raw.get(path);  local = per_file_free[path];  imps = per_file_imports[path]
    if txt is None:
