            mod = imps.get(name)
            if mod is None:
                ambiguous += 1
            else:
                matched = matcher(mod, path, cross)
                if len(matched) == 1:
                    fixable_1 += 1; fanout_fixable.append(len(cross))
                elif len(matched) == 0:
                    external += 1
                else:
                    narrow_multi += 1

n = max(fm_sites, 1)
print(f"corpus {os.path.basename(root)}: files={len(files)}  FREE_MULTI sites~{fm_sites} edges~{fm_edges}")
print(f"  fixable->Exact (import narrows to 1) : {fixable_1:5d}  ({100*fixable_1/n:.1f}%)  "
      f"collapses {sum(fanout_fixable)} edges -> {len(fanout_fixable)}")
print(f"  import narrows to >1 (path collision): {narrow_multi:5d}  ({100*narrow_multi/n:.1f}%)")
print(f"  external (import -> no in-repo def)  : {external:5d}  ({100*external/n:.1f}%)")
print(f"  no import of name (ambiguous)        : {ambiguous:5d}  ({100*ambiguous/n:.1f}%)")

